insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('juju-hist-t01','historia','A chegada dos portugueses ao Brasil','treino','Em que ano os portugueses chegaram ao Brasil?','["1500", "1822", "1950", "2000"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t02','historia','A chegada dos portugueses ao Brasil','treino','De qual continente vieram os portugueses?','["África", "Ásia", "Europa", "América"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t03','historia','A chegada dos portugueses ao Brasil','treino','Quem já morava no Brasil quando os portugueses chegaram?','["Os japoneses", "Os povos indígenas", "Os italianos", "Ninguém"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t04','historia','A chegada dos portugueses ao Brasil','treino','Como foi o primeiro encontro entre portugueses e indígenas?','["Os dois povos já se conheciam", "Os dois falavam a mesma língua", "Os dois se vestiam igual", "Os dois povos estranharam um ao outro, porque suas culturas eram muito diferentes"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t05','historia','A chegada dos portugueses ao Brasil','treino','O que os portugueses viram quando chegaram?','["Prédios e carros", "Florestas, rios limpos, muitas aves e os povos indígenas", "Um deserto sem plantas", "Cidades cheias de gente"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t06','historia','A chegada dos portugueses ao Brasil','treino','No começo, os indígenas ajudaram os portugueses a:','["Construir navios de guerra", "Falar português", "Conhecer a mata, os animais, os alimentos e as ervas que curam", "Plantar café"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t07','historia','A chegada dos portugueses ao Brasil','treino','Por que portugueses e indígenas começaram a brigar?','["Porque os portugueses passaram a escravizar os indígenas e impor seus costumes", "Porque os indígenas queriam ir para Portugal", "Porque faltou comida no navio", "Porque eles jogavam futebol"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t08','historia','A chegada dos portugueses ao Brasil','treino','Qual foi a primeira riqueza que os portugueses exploraram no litoral do Brasil?','["O petróleo", "O pau-brasil", "O café", "O ouro"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t09','historia','A chegada dos portugueses ao Brasil','treino','Da cana-de-açúcar os portugueses produziam:','["Leite e queijo", "Pão e bolo", "Melado e rapadura", "Tecido e roupa"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t10','historia','A chegada dos portugueses ao Brasil','treino','Por que os portugueses trouxeram africanos para trabalhar na cana-de-açúcar?','["Porque os africanos já conheciam o cultivo da cana", "Porque os africanos pediram para vir", "Porque era uma viagem de férias", "Porque eles eram portugueses"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t11','historia','A chegada dos portugueses ao Brasil','treino','Por volta de 1850, quem começou a chegar para trabalhar no lugar dos escravizados?','["Os indígenas", "Os astronautas", "Os imigrantes europeus e asiáticos", "Os portugueses de 1500"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t12','historia','A chegada dos portugueses ao Brasil','treino','A pizza e a macarronada chegaram ao Brasil com os imigrantes:','["japoneses", "italianos", "alemães", "africanos"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t13','historia','A chegada dos portugueses ao Brasil','treino','O sushi e o sashimi chegaram ao Brasil com os imigrantes:','["japoneses", "espanhóis", "italianos", "portugueses"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t14','historia','A chegada dos portugueses ao Brasil','treino','O povo brasileiro se formou principalmente pela mistura de:','["Só portugueses", "Indígenas, africanos e europeus", "Só indígenas", "Só imigrantes japoneses"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t15','historia','Povos africanos: povos, culturas e tradições','treino','A África é:','["Um país só, com uma língua", "Uma cidade do Brasil", "Um continente com muitos países e muitas culturas", "Uma ilha pequena"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t16','historia','Povos africanos: povos, culturas e tradições','treino','Qual destas palavras que usamos no dia a dia veio de povos africanos?','["Computador", "Cochicho", "Escola", "Janela"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t17','historia','Povos africanos: povos, culturas e tradições','treino','Qual destas palavras também tem origem africana?','["Bicicleta", "Telefone", "Caderno", "Moleque"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t18','historia','Povos africanos: povos, culturas e tradições','treino','O berimbau, o afoxé e o atabaque são:','["Instrumentos musicais de origem africana", "Comidas africanas", "Danças indígenas", "Roupas portuguesas"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t19','historia','Povos africanos: povos, culturas e tradições','treino','Qual instrumento é muito usado na roda de capoeira?','["Violino", "Piano", "Berimbau", "Flauta"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t20','historia','Povos africanos: povos, culturas e tradições','treino','A capoeira mistura:','["Pintura e escultura", "Luta, dança e música", "Natação e corrida", "Leitura e escrita"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t21','historia','Povos africanos: povos, culturas e tradições','treino','Para os africanos escravizados, os tambores serviam também para:','["Guardar comida", "Fazer barulho para acordar", "Esquentar a casa", "Mandar mensagens, se reunir e contar histórias"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t22','historia','Povos africanos: povos, culturas e tradições','treino','Qual destas danças tem origem africana?','["Maracatu", "Balé", "Valsa", "Tango"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t23','historia','Povos africanos: povos, culturas e tradições','treino','O traje da baiana, com saia rodada, turbante e colares, mostra a influência da cultura:','["japonesa", "africana", "alemã", "italiana"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t24','historia','Povos africanos: povos, culturas e tradições','treino','Qual destes pratos tem influência africana?','["Sushi", "Pizza", "Moqueca", "Salsicha"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t25','historia','Povos africanos: povos, culturas e tradições','treino','Os quilombos eram:','["Lugares escondidos na mata onde viviam os escravizados que fugiam", "Fazendas de cana", "Navios portugueses", "Escolas de música"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t26','historia','Povos africanos: povos, culturas e tradições','treino','Quem são os quilombolas hoje?','["Imigrantes japoneses", "Descendentes de africanos que vivem nas terras dos antigos quilombos", "Turistas", "Portugueses que chegaram em 1500"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t27','historia','Povos africanos: povos, culturas e tradições','treino','Os africanos acreditavam que o criador se mostrava através da:','["Televisão", "Cidade grande", "Natureza: florestas, animais, vento e águas", "Máquina"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-t28','historia','Povos africanos: povos, culturas e tradições','treino','O Brasil é um país laico. Isso quer dizer que:','["Todos devem ter a mesma religião", "Não existe religião no Brasil", "O governo escolhe a religião de cada um", "Não há religião oficial e devemos respeitar a crença de cada um"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p01','historia','A chegada dos portugueses ao Brasil','prova','Os portugueses chegaram ao Brasil em 1500 e encontraram:','["Cidades com muitos prédios", "Os povos indígenas, que já viviam aqui", "Imigrantes italianos", "Uma terra sem ninguém"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p02','historia','A chegada dos portugueses ao Brasil','prova','Qual destes era um costume dos indígenas quando os portugueses chegaram?','["Usar botas e capa", "Andar de carro", "Usar arco e flecha e enfeites de penas", "Falar português"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p03','historia','A chegada dos portugueses ao Brasil','prova','Por que muitos indígenas resistiram aos portugueses?','["Porque não aceitavam ser escravizados e perder seus costumes", "Porque queriam aprender português", "Porque não gostavam de florestas", "Porque queriam morar em Portugal"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p04','historia','A chegada dos portugueses ao Brasil','prova','Qual é a ordem certa dos acontecimentos?','["Imigrantes → pau-brasil → chegada dos portugueses", "Cana-de-açúcar → chegada dos portugueses → pau-brasil", "Pau-brasil → imigrantes → cana-de-açúcar", "Chegada dos portugueses → pau-brasil → cana-de-açúcar → imigrantes"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p05','historia','A chegada dos portugueses ao Brasil','prova','O quibe e a esfirra chegaram ao Brasil com os imigrantes:','["sírio-libaneses", "japoneses", "alemães", "italianos"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p06','historia','A chegada dos portugueses ao Brasil','prova','Qual frase está CERTA?','["Os portugueses vieram da África.", "Os imigrantes chegaram antes dos portugueses.", "Indígenas, africanos e europeus ajudaram a formar o povo brasileiro.", "Os indígenas trouxeram a pizza."]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p07','historia','Povos africanos: povos, culturas e tradições','prova','Os africanos vieram para o Brasil:','["Para passear", "Trazidos à força para trabalhar como escravizados", "Para estudar", "Porque eram portugueses"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p08','historia','Povos africanos: povos, culturas e tradições','prova','Em qual grupo TODAS as palavras são de origem africana?','["Samba, quitanda e fofoca", "Escola, livro e lápis", "Pizza, macarrão e sushi", "Carro, ônibus e trem"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p09','historia','Povos africanos: povos, culturas e tradições','prova','O afoxé e o reco-reco são instrumentos de:','["Sopro", "Teclado", "Percussão", "Corda"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p10','historia','Povos africanos: povos, culturas e tradições','prova','Acarajé, caruru e cocada mostram a influência africana na:','["Música", "Culinária", "Língua", "Arquitetura"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p11','historia','Povos africanos: povos, culturas e tradições','prova','Por que é importante que as terras quilombolas sejam reconhecidas pelo governo?','["Para virarem fazendas de cana", "Para os quilombolas irem embora", "Para ninguém morar lá", "Para as comunidades terem direitos e preservarem sua cultura"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-hist-p12','historia','Povos africanos: povos, culturas e tradições','prova','Respeitar a religião de cada pessoa se chama:','["Tolerância religiosa", "Escravidão", "Imigração", "Colonização"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd');
insert into gabarito (questao_id,correta,explicacao) values
  ('juju-hist-t01',0,'Os portugueses chegaram em 1500, vindos da Europa de navio.'),
  ('juju-hist-t02',2,'Portugal fica na Europa. Os portugueses atravessaram o oceano de navio.'),
  ('juju-hist-t03',1,'Os povos indígenas já viviam aqui muito antes da chegada dos portugueses.'),
  ('juju-hist-t04',3,'Roupas, língua, ferramentas e costumes eram muito diferentes. Foi um grande espanto para os dois lados.'),
  ('juju-hist-t05',1,'A terra tinha florestas enormes, rios de água clara, aves de todos os tipos e os povos indígenas.'),
  ('juju-hist-t06',2,'Os portugueses precisaram dos indígenas para viver na nova terra: comer, morar e conhecer as plantas e os animais.'),
  ('juju-hist-t07',0,'Os portugueses tomaram as terras, obrigaram os indígenas a trabalhar e quiseram mudar o seu jeito de viver.'),
  ('juju-hist-t08',1,'A exploração começou pelo pau-brasil, uma árvore cuja madeira tinha muito valor.'),
  ('juju-hist-t09',2,'A cana-de-açúcar virava melado, rapadura e açúcar, e dava muito lucro.'),
  ('juju-hist-t10',0,'Muitos africanos já sabiam lidar com a cana. Eles foram trazidos à força e escravizados.'),
  ('juju-hist-t11',2,'Italianos, alemães, espanhóis, japoneses e outros imigrantes vieram trabalhar no Brasil.'),
  ('juju-hist-t12',1,'Os italianos trouxeram muitas comidas que adoramos, como pizza e macarronada.'),
  ('juju-hist-t13',0,'Os japoneses se fixaram principalmente em São Paulo e trouxeram o sushi e o sashimi.'),
  ('juju-hist-t14',1,'Indígenas, africanos e europeus, e depois outros imigrantes, formaram juntos o povo brasileiro.'),
  ('juju-hist-t15',2,'A África é um continente enorme, com muitos países, línguas e jeitos de viver.'),
  ('juju-hist-t16',1,'Cochicho, quitanda, fofoca, moleque, camundongo e samba são palavras de origem africana.'),
  ('juju-hist-t17',3,'"Moleque" é uma das muitas palavras africanas que entraram no português do Brasil.'),
  ('juju-hist-t18',0,'São instrumentos muito usados na música brasileira e vieram da cultura africana.'),
  ('juju-hist-t19',2,'O berimbau é um instrumento de corda que marca o ritmo na capoeira.'),
  ('juju-hist-t20',1,'A capoeira é uma expressão afro-brasileira que junta luta (arte marcial), dança e música.'),
  ('juju-hist-t21',3,'Pelos toques do tambor eles se comunicavam, se reuniam e compartilhavam suas histórias.'),
  ('juju-hist-t22',0,'Maracatu, samba de roda, congada, maculelê e bumba meu boi têm influência africana.'),
  ('juju-hist-t23',1,'A roupa da baiana é bem ao estilo afrodescendente.'),
  ('juju-hist-t24',2,'Moqueca, caruru, acarajé e cocada têm influência da culinária africana.'),
  ('juju-hist-t25',0,'Os escravizados fugiam das fazendas e formavam quilombos em lugares seguros da mata. Era uma forma de resistência.'),
  ('juju-hist-t26',1,'Os quilombolas vivem nas terras onde seus antepassados se abrigavam e preservam seus costumes.'),
  ('juju-hist-t27',2,'Para eles, o sagrado aparece na natureza, como nas águas dos rios e do mar.'),
  ('juju-hist-t28',3,'No Brasil convivem muitas religiões. Respeitar a crença de cada um é a tolerância religiosa.'),
  ('juju-hist-p01',1,'Os indígenas foram os primeiros habitantes do Brasil.'),
  ('juju-hist-p02',2,'Os indígenas usavam arco e flecha, cocar e enfeites de penas e pintavam o corpo.'),
  ('juju-hist-p03',0,'Os indígenas não estavam acostumados àquele tipo de trabalho e não queriam mudar seu jeito de viver.'),
  ('juju-hist-p04',3,'Primeiro os portugueses chegaram, depois exploraram o pau-brasil, a cana-de-açúcar e, bem mais tarde, vieram os imigrantes.'),
  ('juju-hist-p05',0,'Os sírio-libaneses trouxeram pratos como o quibe e a esfirra.'),
  ('juju-hist-p06',2,'O povo brasileiro é a mistura de vários povos: indígenas, africanos, europeus e outros imigrantes.'),
  ('juju-hist-p07',1,'Eles foram tirados de suas terras e obrigados a trabalhar, principalmente nas plantações.'),
  ('juju-hist-p08',0,'Samba, quitanda e fofoca vieram de línguas africanas, como a dos bantos.'),
  ('juju-hist-p09',2,'Afoxé e reco-reco fazem som quando chacoalhamos ou raspamos o instrumento: são de percussão.'),
  ('juju-hist-p10',1,'Esses pratos fazem parte da culinária de influência africana.'),
  ('juju-hist-p11',3,'Com as terras reconhecidas, as comunidades podem receber ajuda do governo e manter seus costumes.'),
  ('juju-hist-p12',0,'No Brasil, que é laico, devemos respeitar todas as crenças: isso é tolerância religiosa.');
